-- Rede Praça Nova — vendas e estornos dos PDVs (23/02/2026 a 05/04/2026).
-- Gerado por tools/gen-case-003.ts. Não edite à mão: rode o gerador de novo.

CREATE TABLE stores (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  city TEXT NOT NULL
);

CREATE TABLE cashiers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  store_id INTEGER NOT NULL REFERENCES stores(id),
  role TEXT NOT NULL,
  shift TEXT NOT NULL,
  hired_at TEXT NOT NULL
);

CREATE TABLE transactions (
  id INTEGER PRIMARY KEY,
  store_id INTEGER NOT NULL REFERENCES stores(id),
  register_no INTEGER NOT NULL,
  cashier_id INTEGER NOT NULL REFERENCES cashiers(id),
  sold_at TEXT NOT NULL,
  total REAL NOT NULL,
  payment_method TEXT NOT NULL
);

CREATE TABLE refunds (
  id INTEGER PRIMARY KEY,
  transaction_id INTEGER NOT NULL UNIQUE REFERENCES transactions(id),
  cashier_id INTEGER NOT NULL REFERENCES cashiers(id),
  refunded_at TEXT NOT NULL,
  amount REAL NOT NULL,
  reason TEXT NOT NULL,
  approved_by INTEGER REFERENCES cashiers(id)
);




